  assert(iGuard !== -1 && iReceipt !== -1 && iGuard < iReceipt, 'гейт ДО проверки квитанции (отбой даже при валидной квитанции)');
  assert(iPlan !== -1 && iGuard < iPlan, 'гейт ДО построения плана');
