  assert(/if \(isDryRun\) childEnv\.HM_DRY_RUN = '1';/.test(s), 'dry-run доезжает до install-скрипта ДО spawn');
  const un = s.slice(s.indexOf("ipcMain.handle('uninstall-component'"));
  const iDry = un.indexOf('if (isDryRun) {');
