    const rec = receiptsMod.readReceipt(home, 'uv');
    assert(rec && rec.version === '7.7.7', 'receipt восстановлен из .bak: ' + JSON.stringify(rec));
    assert(fs.existsSync(rp), 'основной файл на месте');
