        assert(o.indexOf('PY=C:\\Py\\python3.exe') !== -1, 'заглушка python пропущена, взят python3: ' + o);
        o = run({ python: 'C:\\Users\\x\\AppData\\Local\\Microsoft\\WindowsApps\\python.exe' });
