    assert(/…$/.test(r.lbl.vscode), 'обрыв подписи виден: ' + r.lbl.vscode);
    assert(r.lbl.vscode.length <= prefix.length + 60, 'подпись не длиннее 59 символов причины и «…»: ' + r.lbl.vscode.length);
