    assert(/Система: Windows 10\.0\.26200 \(x64\)/.test(text), 'ОС');
    assert(/uid: 272540053/.test(text), 'uid');
    assert(/шаг «VS Code — редактор» \(vscode, fail\): код 1 · этап: Ставлю расширение/.test(text), 'шаг и ошибка');
