      reset();
      H.run("renderNetCheck({ kind: 'geo', detail: 'Anthropic отказал по адресу (ответ 403)', " +
        "proxy: { enabled: true, local: true, url: 'http://127.0.0.1:10809', works: true, kind: 'reachable' } })");
      assert(box().classList.contains('warn'));
