      assert(/TUN/.test(box().innerHTML) && !/id="ns-proxy"/.test(box().innerHTML), 'прокси нет — шаги TUN, без кнопки');
      assert(/Для самой установки VPN не нужен/.test(box().innerHTML));
      reset();
